function hydrate(
  src: Record<string, Record<string, Row[]>>
): Record<number, Record<string, Result[]>> {
  const out: Record<number, Record<string, Result[]>> = {};
  for (const year of Object.keys(src)) {
    const byClass: Record<string, Result[]> = {};
    for (const cls of Object.keys(src[year])) {
      byClass[cls] = src[year][cls].map(([rank, team, time]) => ({ rank, team, time }));
    }
    out[Number(year)] = byClass;
  }
  return out;
}

